-- 482: Original BrillaPrep Cambridge A-Level Biology (9700) Biodiversity and Conservation questions (batch alevel-bio-sprint2-001).
-- Curriculum-aligned practice content; not official Cambridge International or WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE _migration_482_expected (id TEXT PRIMARY KEY, topic_id TEXT, subject_id TEXT, exam_type_id TEXT, paper_type_id TEXT, past_paper_id TEXT, question_text TEXT, question_type TEXT, round_type TEXT, options TEXT, correct_answer TEXT, explanation TEXT, difficulty TEXT, points INTEGER, marks INTEGER, time_limit INTEGER, question_number INTEGER, section TEXT, is_compulsory INTEGER, image_url TEXT, syllabus_topic_id TEXT, command_word TEXT, assessment_objective TEXT, source_paper_code TEXT, source_question_number TEXT, exam_board_id TEXT);
INSERT INTO _migration_482_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_albio_biodiversity_s2_001', 'topic_alevel_bio_biodiversity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which statement best defines a species?', 'multiple_choice', NULL, '["A. All the organisms living in the same habitat","B. A group of similar organisms that can interbreed to produce fertile offspring","C. Organisms that share completely identical DNA","D. All the organisms placed in the same genus"]', 'B', 'The biological species concept defines a species by reproductive compatibility: members can interbreed in nature and produce fertile offspring, whereas hybrids between different species (such as the mule) are sterile. Occupying the same habitat describes a community, not a species; individuals of a species vary genetically, so identical DNA is neither possible nor required; and a genus is a taxonomic rank that may contain many species. Therefore the correct answer is B: A group of similar organisms that can interbreed to produce fertile offspring.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_biodiversity_s2_002', 'topic_alevel_bio_biodiversity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which of the following is an example of ex situ conservation?', 'multiple_choice', NULL, '["A. Establishing a national park to protect a savanna ecosystem","B. Declaring a forest reserve where logging is banned","C. Storing seeds in a seed bank away from the species’ natural habitat","D. Restoring a degraded wetland so that native species recolonise it"]', 'C', 'Ex situ means “out of place”: conservation outside the natural habitat, such as seed banks, botanic gardens, zoos and captive breeding programmes. National parks, forest reserves and habitat restoration all protect species within their natural environment, which is in situ conservation — the distinction between the two strategies is a favourite examination target. Therefore the correct answer is C: Storing seeds in a seed bank away from the species’ natural habitat.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_cambridge'),
('q_albio_biodiversity_s2_003', 'topic_alevel_bio_biodiversity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Which change in a habitat would increase the value of Simpson’s index of diversity (D)?', 'multiple_choice', NULL, '["A. One species becoming strongly dominant over all the others","B. A fall in the total number of species present","C. An increase in the physical area of the habitat alone","D. A greater number of species, with individuals more evenly distributed among those species"]', 'D', 'Simpson’s index rises with both species richness (more species) and evenness (similar abundances), because the formula D = 1 − Σ(n/N)² penalises communities dominated by a few species. Strong dominance by one species or a fall in species number lowers D. A larger area may allow more species to exist, but area by itself does not enter the calculation, so it is not a direct cause of a higher index. Therefore the correct answer is D: A greater number of species, with individuals more evenly distributed among those species.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_biodiversity_s2_004', 'topic_alevel_bio_biodiversity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Why is maintaining genetic diversity within a species important for its long-term survival?', 'multiple_choice', NULL, '["A. Genetic variation gives natural selection raw material with which to adapt the population to changing conditions such as new diseases or a shifting climate","B. Genetic diversity directly increases the mutation rate of the population","C. Genetically diverse populations are guaranteed to grow larger","D. Genetic diversity is only important for species kept in captivity"]', 'A', 'A population with high genetic diversity is likely to contain some individuals whose alleles suit new selection pressures, so the population can evolve rather than go extinct when the environment changes. Diversity does not raise the mutation rate — it reflects variation already present; it improves resilience rather than guaranteeing population growth; and it matters for wild populations just as much as captive ones, as bottlenecked species such as the cheetah illustrate. Therefore the correct answer is A: Genetic variation gives natural selection raw material with which to adapt the population to changing conditions such as new diseases or a shifting climate.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_cambridge'),
('q_albio_biodiversity_s2_005', 'topic_alevel_bio_biodiversity', 'subj_alevel_biology', 'cambridge_a2', NULL, NULL, 'Scientists compare the amino acid sequences of the respiratory protein cytochrome c in different species. Species with more similar cytochrome c sequences are interpreted as being…', 'multiple_choice', NULL, '["A. …adapted to more similar habitats, because the environment determines the protein sequence","B. …more closely related, having diverged from a common ancestor more recently, because fewer mutations have accumulated since their lineages split","C. …possessing the same number of chromosomes, since sequence similarity fixes the karyotype","D. …products of convergent evolution, because similar proteins must arise independently"]', 'B', 'Cytochrome c performs the same conserved function in aerobic respiration across species, so differences in its sequence accumulate largely by mutation over time. The fewer the differences between two species, the more recently their lineages shared a common ancestor — the basis of molecular phylogenetics. Habitat similarity does not directly write protein sequences, chromosome number is unrelated to the sequence of a single protein, and shared ancestry — not convergence — is the correct inference for such a conserved molecule. Therefore the correct answer is B: …more closely related, having diverged from a common ancestor more recently, because fewer mutations have accumulated since their lineages split.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Analyse', 'AO2', NULL, NULL, 'board_cambridge');
CREATE TABLE _migration_482_expected_parts (id TEXT PRIMARY KEY, question_id TEXT NOT NULL, part_label TEXT NOT NULL, part_text TEXT NOT NULL, marks INTEGER NOT NULL, correct_answer TEXT NOT NULL, display_order INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS _migration_482_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_482_guard;
INSERT INTO _migration_482_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_482_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_482_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'alevel-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_482_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'alevel-bio-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.', 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/', 0, 1 FROM _migration_482_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
DELETE FROM _migration_482_guard;
INSERT INTO _migration_482_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_482_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 5 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_482_expected e ON e.id = r.question_id WHERE r.batch_id IS 'alevel-bio-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published Cambridge International AS & A Level Biology (9700) syllabus; not official Cambridge International or WAEC examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://www.cambridgeinternational.org/programmes-and-qualifications/cambridge-international-as-and-a-level-biology-9700/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 5 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_482_expected e ON e.id = q.id) = 5 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_482_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 0 THEN 1 ELSE 0 END;
